'use strict';
/* SETCLASS AUDIT — how much harmonic vocabulary does a ternary space have?
 *
 * WHY THIS SET EXISTS
 * -------------------
 * AB5 measured the group generated by the accumulator maps that erase nothing --
 * ADD over every operand, plus NEG -- and found it has order exactly 1,458 on 729
 * states: the translations extended by negation, a vanishing fraction of 729!, and
 * the reason the named ALU cannot compute without an eraser.
 *
 * That group already has a name, in a field that has been studying it since the
 * 1960s. Musical set theory works in Z/12 under TRANSPOSITION T_n(x) = x + n and
 * INVERSION I_n(x) = n - x, and the two together generate the dihedral group of
 * order 24 acting on twelve pitch classes -- the T/I group. AB5's 1,458 is that
 * same construction at n = 729, and its conclusion is the one music theory reached
 * from the other side: T and I preserve interval content, so they can never carry
 * one set class into another.
 *
 * The natural question in the other direction is whether a base-three space is a
 * good place to do that kind of music. It has an obvious structural handicap:
 * TWELVE IS HIGHLY COMPOSITE FOR ITS SIZE and 729 is a prime power. Transposing by
 * k cycles with period n/gcd(k,n), so the available periods are exactly the
 * divisors of n -- and each one in Z/12 is a piece of harmonic vocabulary: the
 * augmented triad at period 3, the diminished seventh at 4, the whole-tone scale
 * at 6. A prime power has a single unbranched chain of subgroups and nothing else.
 *
 * WHAT IS MEASURED
 * ----------------
 * Orbit-length spectra under translation, set-class counts by Burnside's lemma, and
 * the density of transpositionally symmetric subsets, in Z/12 against Z/27 and
 * Z/729. Z/12 is the control: its answers are published and this audit must
 * reproduce them before its ternary answers are worth anything.
 *
 * ------------------------------------------------------------------------------
 * PREDICTED OUTCOMES — registered before the run, per AGENTS.md.
 *
 *   AE1 the group AB5 measured IS the T/I group, and the same code says so. Run
 *       perm-lib's stabiliser chain on translation-by-1 and negation over Z/12,
 *       with no special-casing, and predicted it returns exactly 24 -- the dihedral
 *       group musical set theory calls T/I. Predicted the same construction returns
 *       2n at n = 12, 27 and 729, so AB5's 1,458 is 2 x 729 and not a coincidence
 *       of the tryte width.
 *
 *   AE2 ternary space is DIVISOR-POOR, and that is the handicap. Predicted the
 *       number of distinct translation orbit-lengths equals the divisor count of n
 *       exactly: 6 for Z/12, 4 for Z/27, 7 for Z/729. Predicted the comparison that
 *       makes it vivid is 729 against 720 -- one apart in size -- where 720 has 30
 *       divisors and 729 has 7. Predicted further that every Z/3^k orbit length is
 *       a power of three, so consecutive available periods always differ by a factor
 *       of exactly 3 and there is nothing in between.
 *
 *   AE3 the instrument reproduces published musicology before it is believed. By
 *       Burnside over the T/I group, predicted Z/12 has exactly 224 set classes
 *       counting all cardinalities including the empty set and the aggregate, and
 *       exactly 12 trichord classes and 29 tetrachord classes -- three numbers that
 *       are in the literature and were not derived here. Predicted Z/27 has between
 *       2.4 and 2.6 million set classes, which is close to 2^27 / 54 because at that
 *       size the identity element dominates the average.
 *
 *   AE4 and the vocabulary that actually matters nearly vanishes. A subset with
 *       nontrivial transpositional symmetry is a union of cosets of a nontrivial
 *       subgroup, and those are the chords Western harmony leans on. Predicted the
 *       fraction of subsets having any nontrivial transpositional symmetry is above
 *       2% in Z/12 and below 0.001% in Z/27 -- a drop of more than three orders of
 *       magnitude. Registered with the alternative: if the fractions are comparable,
 *       the subgroup argument above is wrong and prime-power spaces are no worse.
 *
 * ------------------------------------------------------------------------------
 * Run: node tools/setclass-audit.js
 */

const { chainOf } = require('./perm-lib.js');

const MAIN = require.main === module;
const log = (...a) => { if (MAIN) console.log(...a); };
const line = '='.repeat(78);

log('SETCLASS AUDIT — the harmonic vocabulary of a ternary space\n');

const gcd = (a, b) => (b === 0 ? a : gcd(b, a % b));
const divisors = n => { const d = []; for (let i = 1; i <= n; i++) if (n % i === 0) d.push(i); return d; };

/** Transposition T_k and inversion I on Z/n, as permutations of 0..n-1. */
const T = (n, k) => Array.from({ length: n }, (_, x) => (x + k) % n);
const I = n => Array.from({ length: n }, (_, x) => (n - x) % n);

/** Cycle count of a permutation — what Burnside's lemma needs. */
function cycles(g) {
  const seen = new Array(g.length).fill(false);
  let c = 0;
  for (let i = 0; i < g.length; i++) {
    if (seen[i]) continue;
    c++; let j = i;
    while (!seen[j]) { seen[j] = true; j = g[j]; }
  }
  return c;
}
/** The cycle TYPE, as a list of cycle lengths, for the generating-function count. */
function cycleLengths(g) {
  const seen = new Array(g.length).fill(false);
  const out = [];
  for (let i = 0; i < g.length; i++) {
    if (seen[i]) continue;
    let len = 0, j = i;
    while (!seen[j]) { seen[j] = true; j = g[j]; len++; }
    out.push(len);
  }
  return out;
}

/** Every element of the T/I group on Z/n: n transpositions and n inversions. */
function TIgroup(n) {
  const els = [];
  for (let k = 0; k < n; k++) {
    els.push(T(n, k));
    els.push(Array.from({ length: n }, (_, x) => (k - x % n + n * n) % n));   // I_k
  }
  return els;
}

/* ============================================================================
 * 0. INSTRUMENT CHECK
 * ========================================================================== */
log(line);
log('0. INSTRUMENT CHECK');
log(line);
{
  log(`  T_1 on Z/12 is a single 12-cycle: ${cycles(T(12, 1)) === 1}`);
  log(`  T_0 is the identity, 12 fixed points: ${cycles(T(12, 0)) === 12}`);
  log(`  T_6 on Z/12 is six 2-cycles: ${cycles(T(12, 6)) === 6}`);
  log(`  inversion on Z/12 fixes 0 and 6 and swaps the rest: ${cycles(I(12)) === 7}`);
  log(`  the T/I group on Z/12 has 24 elements listed: ${TIgroup(12).length === 24}`);
  log(`  and they are 24 DISTINCT permutations: ${new Set(TIgroup(12).map(g => g.join(','))).size === 24}`);
  // Burnside on a case small enough to check by hand: necklaces of 4 beads, 2
  // colours, under rotation = 6.
  const rot4 = [0, 1, 2, 3].map(k => T(4, k));
  const necklaces = rot4.reduce((s, g) => s + 2 ** cycles(g), 0) / 4;
  log(`  Burnside sanity: 2-colour necklaces of length 4 under rotation = ${necklaces} (must be 6)`);
}

/* ============================================================================
 * 1. AE1 — the group AB5 measured is the T/I group.
 * ========================================================================== */
log('\n' + line);
log('1. AE1 — running AB5\'s construction on twelve pitch classes');
log(line);
{
  log('   n     generators                 order   2n      dihedral');
  log('  ' + '-'.repeat(60));
  for (const n of [12, 27, 729]) {
    const order = chainOf([T(n, 1), I(n)], n).order;
    log(`  ${String(n).padStart(4)}   translation-by-1, negation   ${String(order).padStart(5)}   ${String(2 * n).padStart(5)}   ${order === BigInt(2 * n) ? 'YES' : 'NO'}`);
  }
  log('');
  log('  AB5 measured 1,458 for the zero-erasure ALU on 729 accumulator states.');
  log('  The same two generators on twelve points give the group musical set theory');
  log('  calls T/I. It is one construction, and the tryte width is not special.');
}

/* ============================================================================
 * 2. AE2 — divisor poverty.
 * ========================================================================== */
log('\n' + line);
log('2. AE2 — how many different things can a transposition do?');
log(line);
{
  log('   n     divisors  distinct orbit lengths  the lengths');
  log('  ' + '-'.repeat(70));
  for (const n of [12, 27, 720, 729]) {
    const lens = new Set(Array.from({ length: n }, (_, k) => n / gcd(k === 0 ? n : k, n)));
    const d = divisors(n);
    const shown = [...lens].sort((a, b) => a - b);
    log(`  ${String(n).padStart(4)}   ${String(d.length).padStart(8)}  ${String(lens.size).padStart(22)}  ` +
      (shown.length > 10 ? shown.slice(0, 8).join(' ') + ' ...' : shown.join(' ')));
  }
  log('');
  log(`  720 and 729 are one apart. 720 has ${divisors(720).length} divisors; 729 has ${divisors(729).length}.`);
  log(`  Every Z/3^k period is a power of three, so consecutive available periods`);
  log(`  differ by a factor of exactly 3 and nothing sits between them.`);
  const p27 = [...new Set(Array.from({ length: 27 }, (_, k) => 27 / gcd(k === 0 ? 27 : k, 27)))].sort((a, b) => a - b);
  log(`  Z/27 periods: ${p27.join(' ')}   — no analogue of the whole-tone scale (period 6)`);
  log(`  or the diminished seventh (period 4), because 6 and 4 do not divide 27.`);
}

/* ============================================================================
 * 3. AE3 — set classes, with Z/12 as the control.
 * ========================================================================== */
log('\n' + line);
log('3. AE3 — set-class counts by Burnside, checked against published Z/12 figures');
log(line);

/** Total set classes: (1/|G|) sum over g of 2^cycles(g). */
function setClasses(n) {
  const G = TIgroup(n);
  let total = 0n;
  for (const g of G) total += 2n ** BigInt(cycles(g));
  if (total % BigInt(G.length) !== 0n) throw new Error('Burnside did not divide evenly');
  return total / BigInt(G.length);
}
/** Set classes of each cardinality: coefficient extraction on prod (1 + x^len). */
function byCardinality(n) {
  const G = TIgroup(n);
  const acc = new Array(n + 1).fill(0n);
  for (const g of G) {
    let poly = [1n];
    for (const len of cycleLengths(g)) {
      const next = new Array(poly.length + len).fill(0n);
      for (let i = 0; i < poly.length; i++) { next[i] += poly[i]; next[i + len] += poly[i]; }
      poly = next;
    }
    for (let i = 0; i < poly.length; i++) acc[i] += poly[i];
  }
  return acc.map(v => v / BigInt(G.length));
}
{
  const c12 = setClasses(12), card12 = byCardinality(12);
  log(`  Z/12 total set classes under T/I: ${c12}   (published: 224)`);
  log(`  Z/12 trichord classes: ${card12[3]}   (published: 12)`);
  log(`  Z/12 tetrachord classes: ${card12[4]}   (published: 29)`);
  log(`  Z/12 hexachord classes: ${card12[6]}   (published: 50)`);
  const ok = c12 === 224n && card12[3] === 12n && card12[4] === 29n;
  log(`  the instrument reproduces musicology it did not derive: ${ok ? 'YES' : 'NO — stop here'}`);
  log('');
  const c27 = setClasses(27);
  log(`  Z/27 total set classes under T/I: ${c27}`);
  log(`  2^27 / 54 = ${2n ** 27n / 54n}  (the identity element dominates at this size)`);
  const card27 = byCardinality(27);
  log(`  Z/27 trichord classes: ${card27[3]}    tetrachord classes: ${card27[4]}`);
}

/* ============================================================================
 * 4. AE4 — transpositional symmetry, which is the vocabulary that matters.
 * ========================================================================== */
log('\n' + line);
log('4. AE4 — how many chords have symmetry to work with?');
log(line);

/**
 * Subsets invariant under SOME nontrivial transposition. A set fixed by T_k is a
 * union of cosets of <k>, so it is counted by 2^(n/order) — and inclusion-exclusion
 * over the subgroup lattice avoids counting the same subset twice. Small enough to
 * do directly: mark every invariant subset in a bitset for n <= 27.
 */
function symmetricFraction(n) {
  const invariant = new Set();
  for (let k = 1; k < n; k++) {
    const period = n / gcd(k, n);
    if (period === n) continue;                 // T_k generates everything: only 0 and all
    const cosets = gcd(k, n);
    for (let mask = 0; mask < 2 ** cosets; mask++) {
      let s = 0n;
      for (let c = 0; c < cosets; c++) if (mask & (1 << c)) for (let j = c; j < n; j += cosets) s |= 1n << BigInt(j);
      invariant.add(s);
    }
  }
  invariant.delete(0n);
  invariant.delete((1n << BigInt(n)) - 1n);      // empty and full are trivially symmetric
  return { count: invariant.size, total: 2 ** n };
}
{
  log('   n     subsets        with nontrivial transpositional symmetry   fraction');
  log('  ' + '-'.repeat(72));
  const rows = [];
  for (const n of [12, 27]) {
    const { count, total } = symmetricFraction(n);
    rows.push({ n, count, total, frac: count / total });
    log(`  ${String(n).padStart(4)}   ${String(total).padStart(11)}   ${String(count).padStart(38)}   ${(100 * count / total).toPrecision(3)}%`);
  }
  const [a, b] = rows;
  log('');
  log(`  ratio of fractions: Z/12 is ${(a.frac / b.frac).toPrecision(4)}x richer in symmetric subsets`);
  log(`  orders of magnitude: ${Math.log10(a.frac / b.frac).toFixed(1)}`);
  log('');
  log('  Those are the chords Western harmony leans on -- the augmented triad, the');
  log('  diminished seventh, the whole-tone scale. A prime-power space has a single');
  log('  unbranched chain of subgroups and almost none of them.');
}

log('\n' + line);
log('Registered predictions AE1-AE4 are in this file\'s docstring. Outcomes go to');
log('FINDINGS.json and are asserted in test/test-setclass.js.');
log(line);

module.exports = { T, I, TIgroup, cycles, cycleLengths, setClasses, byCardinality, symmetricFraction, divisors, gcd };
